// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public {
        c = new TimelockController(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes32 role, address account) public {
        // Admissible domain: any role not explicitly configured in the constructor.
        vm.assume(
            role != c.TIMELOCK_ADMIN_ROLE() &&
            role != c.PROPOSER_ROLE() &&
            role != c.EXECUTOR_ROLE()
        );

        // General rule: an arbitrary (unconfigured) role has no members, so no
        // account holds it; hasRole must report false for every account.
        bool ok = c.hasRole(role, account);
        assertTrue(!ok);
    }
}
